changeSet.sql:
create index if not exists idx_orders_active_created_at
    on orders (created_at) where deleted = false;
create index if not exists idx_orders_active_status_created_at
    on orders (status, created_at) where deleted = false;
create index if not exists idx_orders_active_user_created_at
    on orders (user_id, created_at desc) where deleted = false;

rollback.sql:
drop index if exists idx_orders_active_created_at;
drop index if exists idx_orders_active_status_created_at;
drop index if exists idx_orders_active_user_created_at;
alter table order_items drop constraint if exists uk_order_items_order_item;
